    private function search_ubigeo_info($ubigeos, $filters = []) {
        foreach ($ubigeos as $ubigeo) {
            $coincidences = 0;
            foreach ($filters as $col => $value) {
                if (isset($ubigeo[$col]) && $this->clear_string($ubigeo[$col]) == $this->clear_string($value)) {
                    $coincidences++;
                }
            }

            if ($coincidences == count($filters)) {
                return $ubigeo;
            }
        }
     
        return false;
    }

