    private function get_data_eplani()
    {
      $this->db->from('tbl_eplani_ubigeos');
      $results = $this->db->get()->result();

      $data_ubigeos = [];

      foreach ($results as $row) {
        $data_ubigeos[$this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $row->order_administrative1))][$this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $row->order_administrative2))][$this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $row->order_administrative3))] = trim($row->code);
      }

      return $data_ubigeos;
    }

    private function get_ubigeo_code($ubigeo)
    {
      $ubigeo_eplani = $this->get_data_eplani();

      $order_administrative1 = $this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $ubigeo->order_administrative1));
      $order_administrative2 = $this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $ubigeo->order_administrative2));
      $order_administrative3 = $this->clear_string(str_replace(['ñ', 'Ñ'], ['n', 'N'], $ubigeo->order_administrative3));

      return $ubigeo_eplani[$order_administrative1][$order_administrative2][$order_administrative3] ?? false;
    }

    private function clear_string($string) {
        $table = [
            'Á' => 'A', 'É' => 'E', 'Í' => 'I', 'Ó' => 'O', 'Ú' => 'U',
            'á' => 'a', 'é' => 'e', 'í' => 'i', 'ó' => 'o', 'ú' => 'u',
            'À' => 'A', 'È' => 'E', 'Ì' => 'I', 'Ò' => 'O', 'Ù' => 'U',
            'à' => 'a', 'è' => 'e', 'ì' => 'i', 'ò' => 'o', 'ù' => 'u',
            'Ä' => 'A', 'Ë' => 'E', 'Ï' => 'I', 'Ö' => 'O', 'Ü' => 'U',
            'ä' => 'a', 'ë' => 'e', 'ï' => 'i', 'ö' => 'o', 'ü' => 'u',
            'Â' => 'A', 'Ê' => 'E', 'Î' => 'I', 'Ô' => 'O', 'Û' => 'U',
            'â' => 'a', 'ê' => 'e', 'î' => 'i', 'ô' => 'o', 'û' => 'u',
        ];
        
        $string = strtr($string, $table);
           
        return mb_strtolower(trim($string));
    }
